arguments.command:
cat << 'EOF' > /app/test_radar.mmd
radar-beta
  title Digital Divide Gaps
  axis Income Gap, Age Gap, Location Gap
  curve Sub-Saharan Africa {62, 33, 29}
  curve South Asia {66, 47, 36}
  curve Europe {25, 40, 14}
  curve North America {24, 34, 15}
EOF
npx -y @mermaid-js/mermaid-cli -i /app/test_radar.mmd -o /app/test_radar.png

